INSERT INTO lookup_type (lookup_type_descr, lookup_type_code, lookup_type_active, modifiable, sort_strategy)
VALUES ('Order Type', 'ORDER_TYPE', 1, 1, 1);
SET
@lookupTypeCode = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'ORDER_TYPE');
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, lookup_value_active, sort_seq)
VALUES (@lookupTypeCode, 'Move', 'Move', 1, 1);
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, lookup_value_active, sort_seq)
VALUES (@lookupTypeCode, 'Add', 'Add', 1, 2);
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, lookup_value_active, sort_seq)
VALUES (@lookupTypeCode, 'Change', 'Change', 1, 3);
INSERT INTO lookup_value (lookup_type_id, lookup_display, lookup_value, lookup_value_active, sort_seq)
VALUES (@lookupTypeCode, 'Disconnect', 'Disconnect', 1, 4);

