INSERT INTO milestone (milestone_name, milestone_code) VALUES ('Removed from Inventory', 'REMOVED_FROM_INVENTORY');
SET @displaySetId = (SELECT milestone_display_set_id FROM milestone_display_set mds WHERE mds.display_group = 'LOCATION_MILESTONE');
INSERT INTO milestone_display_set_include (milestone_display_set_id, milestone_id, milestone_active, milestone_sequence,
                                           milestone_required, adjustable, workflow_driven, has_time, disallow_future)
VALUES (@displaySetId, (SELECT milestone_id FROM milestone WHERE milestone_code = 'REMOVED_FROM_INVENTORY'), 1, 1040, 0, 1, 1, 0, 0)

set @lookupTypeId = (select lookup_type_id from lookup_type where lookup_type_code = 'DISCONNECT_REASON');
insert into tenant_lookup_value (lookup_value_id, tenant_id)
select lookup_value_id, tenant_id from lookup_value, v_tenant where lookup_type_id = @lookupTypeId;

update lookup_type set lookup_type_code = 'DISCONNECT_REASON', lookup_type_descr = 'Disconnect Reason' where lookup_type_code = 'DISCONNECT_TYPE';
set @lookupTypeId = (select lookup_type_id from lookup_type where lookup_type_code = 'DISCONNECT_REASON');
insert into tenant_lookup_value (lookup_value_id, tenant_id)
select lookup_value_id, tenant_id from lookup_value, v_tenant where lookup_type_id = @lookupTypeId;

UPDATE service
SET early_termination_fee = 0
WHERE early_termination_fee IS NULL;

set @lookupTypeId = (select lookup_type_id from lookup_type where lookup_type_code = 'ORDER_TYPE');
insert into tenant_lookup_value (lookup_value_id, tenant_id)
select lookup_value_id, tenant_id from lookup_value, v_tenant where lookup_type_id = @lookupTypeId;
set @lookupTypeId = (select lookup_type_id from lookup_type where lookup_type_code = 'SUB_ORDER_TYPE');
insert into tenant_lookup_value (lookup_value_id, tenant_id)
select lookup_value_id, tenant_id from lookup_value, v_tenant where lookup_type_id = @lookupTypeId;

update milestone_display_set_include set milestone_sequence = 1030
                  where milestone_id = (select milestone_id from milestone where milestone_code = 'BILLING_REVIEW_COMPLETE')
                  and milestone_display_set_id = (select milestone_display_set_id from milestone_display_set where display_group = 'DISCONNECT_MILESTONE');
